'use client';

// Speaking Alita's replies. Server-side voices (Edge, ElevenLabs, OpenAI) are
// generated by the backend and played through one shared <audio> element;
// the "browser" provider uses the device's Web Speech API instead. Small
// external stores keep every speaker button, the auto-speak toggle and
// settings in sync.

import { useEffect, useSyncExternalStore } from 'react';
import * as api from './api';
import type { VoiceStatus } from './types';

export type PlayState = 'idle' | 'loading' | 'playing';

function store<T>(initial: T) {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    get: () => value,
    set: (next: T) => {
      value = next;
      listeners.forEach((l) => l());
    },
    subscribe: (l: () => void) => {
      listeners.add(l);
      return () => listeners.delete(l);
    },
  };
}

// ─── Playback ──────────────────────────────────────────────────────

const IDLE = { key: null as string | null, state: 'idle' as PlayState };
const playback = store(IDLE);
let audio: HTMLAudioElement | null = null;
let token = 0;
let speakingText = '';
let segmentDone: (() => void) | null = null;
const streamedKeys = new Set<string>();
const speechQueue: {
  key: string | null;
  items: string[];
  active: boolean;
  runId: number;
  onError?: (message: string) => void;
} = { key: null, items: [], active: false, runId: 0 };

function release() {
  if (!audio) return;
  audio.onplaying = audio.onended = audio.onerror = null;
  audio.pause();
  audio.removeAttribute('src');
  audio.load();
  audio = null;
}

function stopBrowserSpeech() {
  try {
    window.speechSynthesis?.cancel();
  } catch {
    /* unsupported */
  }
}

export function stopSpeaking() {
  token++;
  speakingText = '';
  speechQueue.runId++;
  speechQueue.key = null;
  speechQueue.items = [];
  speechQueue.active = false;
  speechQueue.onError = undefined;
  const finish = segmentDone;
  segmentDone = null;
  finish?.();
  release();
  stopBrowserSpeech();
  playback.set(IDLE);
}

const clamp = (n: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, n));

/** Speak with the device voices (the "browser" provider). */
function speakLocally(key: string, text: string, status: VoiceStatus, fail: (m: string) => void) {
  const synth = typeof window !== 'undefined' ? window.speechSynthesis : undefined;
  if (!synth || typeof SpeechSynthesisUtterance === 'undefined') {
    fail('This browser has no speech synthesis. Choose a server voice instead.');
    return;
  }
  const mine = token;
  const utter = new SpeechSynthesisUtterance(text);
  const wanted = status.voice?.voice_id;
  const voices = synth.getVoices();
  const chosen =
    (wanted && voices.find((v) => v.name === wanted)) ||
    voices.find((v) => v.lang?.toLowerCase().startsWith('en-gb')) ||
    voices.find((v) => v.lang?.toLowerCase().startsWith('en')) ||
    voices[0];
  if (chosen) utter.voice = chosen;
  utter.rate = clamp(status.settings?.speed ?? 1, 0.5, 2);
  utter.onstart = () => mine === token && playback.set({ key, state: 'playing' });
  utter.onend = () => mine === token && playback.set(IDLE);
  utter.onerror = (e) => {
    if (mine !== token) return;
    playback.set(IDLE);
    if (e.error !== 'interrupted' && e.error !== 'canceled') fail(`Speech failed: ${e.error || 'unknown error'}`);
  };
  synth.cancel();
  synth.speak(utter);
}

/** Speak `text` for the message identified by `key`. Errors go to `onError`. */
export async function speak(key: string, text: string, onError?: (message: string) => void) {
  stopSpeaking();
  const mine = ++token;
  playback.set({ key, state: 'loading' });
  const fail = (message: string) => {
    if (mine !== token) return;
    release();
    stopBrowserSpeech();
    playback.set(IDLE);
    onError?.(message);
  };

  const status = playbackStatus();
  if (status?.provider === 'browser') {
    speakLocally(key, text, status, fail);
    return;
  }

  try {
    const prepared = await api.prepareSpeech(text);
    if (mine !== token) return;
    const el = new Audio(api.withToken(prepared.url));
    audio = el;
    el.onplaying = () => mine === token && playback.set({ key, state: 'playing' });
    el.onended = () => {
      if (mine !== token) return;
      release();
      playback.set(IDLE);
    };
    el.onerror = async () => {
      const state = await api.getSpeechState(prepared.id).catch(() => null);
      fail(state?.error || 'Could not play the audio.');
    };
    await el.play();
  } catch (e) {
    if (e instanceof DOMException && e.name === 'NotAllowedError') {
      fail('The browser blocked autoplay. Click the speaker button to listen.');
    } else if (e instanceof DOMException && e.name === 'AbortError') {
      // Replaced by another reply or stopped.
    } else {
      fail(api.errorMessage(e));
    }
  }
}

/** Streamed replies are fed here sentence by sentence so speech starts early. */
export function enqueueSpeech(key: string, text: string, onError?: (message: string) => void) {
  const clean = text.trim();
  if (!clean) return;
  if (speechQueue.key !== key) {
    stopSpeaking();
    speechQueue.key = key;
  }
  speechQueue.onError = onError || speechQueue.onError;
  speechQueue.items.push(clean);
  if (!speechQueue.active) void runQueue(key, speechQueue.runId);
}

/** Text currently being spoken (used to reject microphone echo). */
export function getSpeakingText(): string {
  return speakingText;
}

/** Lower the current audio volume briefly for a responsive barge-in. */
export function duckSpeech(volume: number = 0.2) {
  if (audio) audio.volume = Math.min(1, Math.max(0, volume));
}

export function markStreamedSpeech(key: string) {
  streamedKeys.add(key);
  if (streamedKeys.size > 80) {
    const first = streamedKeys.values().next().value;
    if (first) streamedKeys.delete(first);
  }
}

function queueError(message: string) {
  const notify = speechQueue.onError;
  stopSpeaking();
  notify?.(message);
}

function playBrowserSegment(
  key: string,
  text: string,
  status: VoiceStatus,
  mine: number,
): Promise<boolean> {
  const synth = typeof window !== 'undefined' ? window.speechSynthesis : undefined;
  if (!synth || typeof SpeechSynthesisUtterance === 'undefined') {
    queueError('This browser has no speech synthesis. Choose a server voice instead.');
    return Promise.resolve(false);
  }
  const utter = new SpeechSynthesisUtterance(text);
  const voices = synth.getVoices();
  const wanted = status.voice?.voice_id;
  const chosen =
    (wanted && voices.find((v) => v.name === wanted)) ||
    voices.find((v) => v.lang?.toLowerCase().startsWith('en-gb')) ||
    voices.find((v) => v.lang?.toLowerCase().startsWith('en')) ||
    voices[0];
  if (chosen) utter.voice = chosen;
  utter.rate = clamp(status.settings?.speed ?? 1, 0.5, 2);
  speakingText = text;
  return new Promise<boolean>((resolve) => {
    let settled = false;
    const finish = (ok: boolean) => {
      if (settled) return;
      settled = true;
      segmentDone = null;
      resolve(ok);
    };
    segmentDone = () => finish(false);
    utter.onstart = () => {
      if (mine === token) playback.set({ key, state: 'playing' });
    };
    utter.onend = () => finish(true);
    utter.onerror = (e) => {
      if (e.error === 'interrupted' || e.error === 'canceled') {
        finish(false);
        return;
      }
      finish(false);
      if (mine === token) queueError(`Speech failed: ${e.error || 'unknown error'}`);
    };
    synth.speak(utter);
  });
}

async function playServerSegment(key: string, text: string, mine: number): Promise<boolean> {
  let prepared;
  try {
    prepared = await api.prepareSpeech(text);
  } catch (e) {
    if (mine === token) queueError(api.errorMessage(e));
    return false;
  }
  if (mine !== token) return false;
  const el = new Audio(api.withToken(prepared.url));
  audio = el;
  speakingText = text;
  return new Promise<boolean>((resolve) => {
    let settled = false;
    const finish = (ok: boolean) => {
      if (settled) return;
      settled = true;
      segmentDone = null;
      resolve(ok);
    };
    segmentDone = () => finish(false);
    el.onplaying = () => {
      if (mine === token) playback.set({ key, state: 'playing' });
    };
    el.onended = () => {
      if (mine === token) release();
      finish(true);
    };
    el.onerror = async () => {
      const state = await api.getSpeechState(prepared.id).catch(() => null);
      if (mine === token) release();
      finish(false);
      if (mine === token) queueError(state?.error || 'Could not play the audio.');
    };
    el.play().catch((e) => {
      if (mine !== token) {
        finish(false);
      } else if (e instanceof DOMException && e.name === 'NotAllowedError') {
        finish(false);
        queueError('The browser blocked autoplay. Click the speaker button to listen.');
      } else if (e instanceof DOMException && e.name === 'AbortError') {
        finish(false);
      } else {
        finish(false);
        queueError(api.errorMessage(e));
      }
    });
  });
}

async function runQueue(key: string, runId: number) {
  if (speechQueue.active) return;
  speechQueue.active = true;
  const mine = token;
  try {
    if (!playbackStatus()) await refreshVoiceStatus();
    const status = playbackStatus();
    if (!status?.configured) {
      return;
    }
    while (
      speechQueue.runId === runId &&
      speechQueue.key === key &&
      mine === token &&
      speechQueue.items.length > 0
    ) {
      const text = speechQueue.items.shift()!;
      playback.set({ key, state: 'loading' });
      const ok = status.provider === 'browser'
        ? await playBrowserSegment(key, text, status, mine)
        : await playServerSegment(key, text, mine);
      if (!ok || speechQueue.runId !== runId || speechQueue.key !== key || mine !== token) return;
    }
  } finally {
    if (speechQueue.runId === runId) {
      speechQueue.active = false;
      if (speechQueue.key === key && mine === token) {
        speechQueue.key = null;
        speechQueue.items = [];
        speechQueue.onError = undefined;
        speakingText = '';
        playback.set(IDLE);
      }
    }
  }
}

/** Strip fenced code from streamed markdown before it reaches TTS. */
export function speechText(markdown: string): string {
  return (markdown || '').replace(/```[\s\S]*?(?:```|$)/g, ' ');
}

/** Return the next natural chunk to enqueue, and how much text it consumed. */
export function nextSpeechChunk(text: string, final: boolean): { text: string; consumed: number } {
  if (!text) return { text: '', consumed: 0 };
  const sentences = /[.!?…]+["')\]]*(?:\s+|$)/g;
  const match = sentences.exec(text);
  if (match) {
    const end = match.index + match[0].length;
    const chunk = text.slice(0, end).trim();
    if (chunk) return { text: chunk, consumed: end };
  }
  const paragraph = text.indexOf('\n\n');
  if (paragraph > 0) {
    const chunk = text.slice(0, paragraph).trim();
    if (chunk) return { text: chunk, consumed: paragraph + 2 };
  }
  if (final) return { text: text.trim(), consumed: text.length };
  const max = 220;
  if (text.length >= max) {
    const space = text.lastIndexOf(' ', max);
    const end = space > 80 ? space : max;
    return { text: text.slice(0, end).trim(), consumed: end };
  }
  return { text: '', consumed: 0 };
}

export function usePlayback(key: string): PlayState {
  const snap = useSyncExternalStore(playback.subscribe, playback.get, () => IDLE);
  return snap.key === key ? snap.state : 'idle';
}

/** Current shared playback state (for hands-free conversation turn-taking). */
export function getPlaybackState() {
  return playback.get();
}

export function subscribePlayback(listener: () => void) {
  return playback.subscribe(listener);
}

// ─── Voice status (which provider/voice?) ──────────────────────────

const status = store<VoiceStatus | null>(null);
let loading: Promise<void> | null = null;

function playbackStatus(): VoiceStatus | null {
  return status.get();
}

export function refreshVoiceStatus(): Promise<void> {
  loading = api
    .getVoiceStatus()
    .then((s) => status.set(s))
    .catch(() => undefined)
    .finally(() => {
      loading = null;
    });
  return loading;
}

export function useVoiceStatus(): VoiceStatus | null {
  const value = useSyncExternalStore(status.subscribe, status.get, () => null);
  useEffect(() => {
    if (status.get() === null && !loading) void refreshVoiceStatus();
  }, []);
  return value;
}

/** Device voices (for the "browser" provider), kept in sync with the browser. */
export function browserVoices(): SpeechSynthesisVoice[] {
  if (typeof window === 'undefined' || !window.speechSynthesis) return [];
  return window.speechSynthesis.getVoices();
}

const browserVoiceListing = store<SpeechSynthesisVoice[]>([]);

export function useBrowserVoices(): SpeechSynthesisVoice[] {
  useEffect(() => {
    if (typeof window === 'undefined' || !window.speechSynthesis) return;
    const update = () => browserVoiceListing.set(browserVoices());
    update();
    window.speechSynthesis.addEventListener?.('voiceschanged', update);
    return () => window.speechSynthesis.removeEventListener?.('voiceschanged', update);
  }, []);
  return useSyncExternalStore(browserVoiceListing.subscribe, browserVoiceListing.get, () => []);
}

// ─── Auto-speak preference (per browser) ───────────────────────────

const AUTO_KEY = 'alita:auto-speak';
const autoSpeak = store(false);
let autoLoaded = false;

function loadAuto() {
  if (autoLoaded || typeof window === 'undefined') return;
  autoLoaded = true;
  try {
    autoSpeak.set(window.localStorage.getItem(AUTO_KEY) === '1');
  } catch {
    /* storage unavailable */
  }
}

export function setAutoSpeak(on: boolean) {
  autoSpeak.set(on);
  if (!on) stopSpeaking();
  try {
    window.localStorage.setItem(AUTO_KEY, on ? '1' : '0');
  } catch {
    /* storage unavailable */
  }
}

export function useAutoSpeak(): boolean {
  const value = useSyncExternalStore(autoSpeak.subscribe, autoSpeak.get, () => false);
  useEffect(loadAuto, []);
  return value;
}

/** Called when a reply finishes streaming in this tab. */
export function maybeAutoSpeak(key: string, text: string, onError?: (message: string) => void) {
  loadAuto();
  const s = status.get();
  if (streamedKeys.has(key)) return;
  if (!autoSpeak.get() || !text.trim() || !s?.configured || !s.voice) return;
  void speak(key, text, onError);
}
